<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import FileDropzone from '../components/FileDropzone.vue';
import ResultDialog from '../components/ResultDialog.vue';
import Range from '../components/RangeControl.vue';
import { dashboardStats, embedWatermark, listImages } from '../api/trace.js';
import { createWatermarkForm, watermarkFormData } from '../forms/watermark.js';
import { createAsyncGuard, safeImageUrl } from './result-format.js';

const props = defineProps({ currentUser: Object });
const form = ref(createWatermarkForm(props.currentUser?.username || ''));
const file = ref(null); const result = ref(null); const dialogOpen = ref(false); const busy = ref(false);
const todayWatermarkCount = ref(0); const detectionSuccessRate = ref('0.0%'); let closeTimer;
const asyncGuard = createAsyncGuard();
watch(() => props.currentUser?.username, userId => { form.value.userId = userId || ''; });
const range = key => computed(() => Number(form.value[key]).toFixed(2));
function isV4(r) { return Number.parseInt(r.robust_watermark_version, 10) === 4 || String(r.code_recovery?.codec || r.robust_watermark_codec || '').endsWith('_v4'); }
const resultRows = computed(() => { if (!result.value) return []; const r = result.value; const scores = r.layer_scores || {}; return [['用户标识', r.user_id], ['Trace ID', r.trace_id], ['证据 UUID 前段', r.evidence_uuid_head || '-'], ['证据 UUID 后段', r.evidence_uuid_tail || '-'], ['水印模式', r.mode_label || r.mode], ['水印版本', `V${[1,2,3,4].includes(Number(r.robust_watermark_version)) ? Number(r.robust_watermark_version) : 1}`], ['生成时间', r.created_at], ['置信度', `${Number(r.confidence || 0)}%`], [isV4(r) ? 'V4 认证载荷' : '频域评分', isV4(r) ? '认证 DCT · FFT 同步' : `DCT ${Number(scores.dct || 0).toFixed(2)} · DWT ${Number(scores.dwt || 0).toFixed(2)} · FFT ${Number(scores.fft || 0).toFixed(2)}`]]; });
async function refreshDashboard() { try { const stats = await dashboardStats(); if (!asyncGuard.isActive()) return; todayWatermarkCount.value = stats.today ?? 0; detectionSuccessRate.value = `${Number(stats.detection_success_rate || 0).toFixed(1)}%`; } catch (_) {} }
async function embed() { if (!file.value) { alert('请选择要生成水印的图片'); return; } busy.value = true; try { const response = await embedWatermark(watermarkFormData(file.value, form.value)); if (!asyncGuard.isActive()) return; result.value = response; await Promise.all([listImages(), refreshDashboard()]); if (!asyncGuard.isActive()) return; dialogOpen.value = true; clearTimeout(closeTimer); closeTimer = setTimeout(() => { if (asyncGuard.isActive()) dialogOpen.value = false; }, 3000); } catch (error) { if (asyncGuard.isActive()) alert(error.message); } finally { if (asyncGuard.isActive()) busy.value = false; } }
onMounted(refreshDashboard); onBeforeUnmount(() => { asyncGuard.dispose(); clearTimeout(closeTimer); });
</script>
<template>
<section class="page-content"><div class="page-header"><div class="page-title">生成水印</div><div class="page-subtitle">为图片嵌入多层隐式水印，支持截图追踪与版权保护</div><div class="tag-row"><span class="tag tag-blue"><i class="ti ti-cpu"></i> DCT 频域水印</span><span class="tag tag-teal"><i class="ti ti-maximize"></i> 扩频空间域</span><span class="tag tag-purple"><i class="ti ti-fingerprint"></i> pHash 指纹</span><span class="tag tag-amber"><i class="ti ti-lock"></i> EXIF 加密</span></div></div>
<div class="grid-2"><div><div class="card"><div class="card-label">基础配置</div><div class="field-group"><label>用户标识 (user_id)</label><input v-model="form.userId" class="field-input" placeholder="输入用户 ID"></div><div class="field-group"><label>盲水印模式</label><select v-model="form.mode" class="field-select"><option value="dct">DCT + 空间域</option><option value="lsb">仅空间域</option><option value="dwt">DWT + 空间域</option><option value="fft">FFT + 空间域</option><option value="hybrid">全部算法（DCT + DWT + FFT + 空间域）</option></select></div></div>
<div class="card"><div class="card-label">高级选项</div><div class="advanced-section"><div class="advanced-title">保护层状态</div><div class="advanced-desc">展示当前已启用的基础抗裁剪能力。</div><span class="inline-status">已内置启用</span><label class="checkbox-row"><input checked disabled type="checkbox"><span class="cb-content"><span class="cb-title">启用块级水印（抗裁剪）</span><span class="cb-desc">后端当前始终写入块级 LSB 冗余，裁剪后仍可尝试提取。</span></span></label></div>
<div class="advanced-section"><div class="advanced-title">版权水印</div><div class="advanced-desc">需要可见版权保护时启用，未启用时不写入版权水印。</div><label class="checkbox-row"><input v-model="form.copyrightEnabled" type="checkbox"><span class="cb-content"><span class="cb-title">启用版权水印（抗 AI 去除）</span><span class="cb-desc">采用对抗性噪声抵抗 AI 图像清洗攻击</span></span></label><div v-if="form.copyrightEnabled"><div class="field-group"><label>版权水印内容</label><input v-model="form.copyrightText" class="field-input" placeholder="输入版权水印内容"></div><label class="checkbox-row"><input v-model="form.copyrightIrregularEnabled" type="checkbox"><span class="cb-content"><span class="cb-title">启用无规则版权水印</span><span class="cb-desc">随机变化位置、角度、字号和透明度，降低固定规则去除成功率</span></span></label><label class="checkbox-row"><input v-model="form.copyrightProminentCornerEnabled" type="checkbox"><span class="cb-content"><span class="cb-title">右下角醒目标注</span><span class="cb-desc">使用亮黄色文字、黑色描边和深色衬底清晰标注版权</span></span></label><Range label="版权水印透明度" v-model="form.copyrightOpacity" :value="range('copyrightOpacity')" min="0.02" max="0.90" step="0.01"/><div class="field-group"><label>版权水印复杂度</label><select v-model="form.copyrightComplexity" class="field-select"><option value="low">低 — 单角度，稀疏</option><option value="medium">中 — 单角度，密集</option><option value="high">高 — 双角度，密集</option><option value="extreme">极 — 三角度，最密</option></select></div></div></div>
<div class="advanced-section"><div class="advanced-title">鲁棒性调优</div><div class="advanced-desc">平衡视觉保真、局部截图恢复和隐藏扰动强度。</div><Range label="图片保真度" v-model="form.fidelityLevel" :value="range('fidelityLevel')"/><label class="checkbox-row"><input v-model="form.smallCropTraceEnabled" type="checkbox"><span class="cb-content"><span class="cb-title">启用小面积截图增强</span><span class="cb-desc">增加局部截图 trace 冗余，会轻微增加隐藏扰动</span></span></label><Range label="小截图增强强度" v-model="form.smallCropTraceStrength" :value="range('smallCropTraceStrength')"/><div class="field-group"><label>小截图增强密度</label><select v-model="form.smallCropTraceDensity" class="field-select"><option value="low">低</option><option value="medium">中</option><option value="high">高</option></select></div><label class="checkbox-row"><input v-model="form.dotMatrixTraceEnabled" type="checkbox"><span class="cb-content"><span class="cb-title">启用点阵追溯水印</span><span class="cb-desc">写入类似打印机微点阵的 trace 冗余，提升局部截图追溯能力</span></span></label><Range label="点阵追溯强度" v-model="form.dotMatrixTraceStrength" :value="range('dotMatrixTraceStrength')"/></div></div></div>
<div><div class="card"><div class="card-label">上传图片</div><FileDropzone v-model:file="file" label="将原始图片拖移至此" hint="支持 JPG、PNG、WEBP，最大 50MB"><template #after-preview><div v-if="result" class="result-box embed-result"><div class="result-title"><i class="ti ti-circle-check"></i> 水印数据</div><div v-for="([label, value]) in resultRows" :key="label" class="result-row"><span class="result-key">{{ label }}</span><span class="result-val">{{ value || '-' }}</span></div><div class="result-row"><span class="result-key">保护状态</span><span class="result-val"><span class="status-badge badge-green">{{ result.status }}</span></span></div><div class="result-actions"><a v-if="safeImageUrl(result.download_url)" class="result-link" :href="safeImageUrl(result.download_url)" target="_blank" rel="noopener"><i class="ti ti-download"></i> 打开水印图</a><a v-if="safeImageUrl(result.original_url)" class="result-link" :href="safeImageUrl(result.original_url)" target="_blank" rel="noopener"><i class="ti ti-photo"></i> 打开原图</a></div></div></template></FileDropzone><button class="btn-primary embed-button" :disabled="busy" @click="embed"><i class="ti" :class="busy ? 'ti-loader' : 'ti-droplet-filled'"></i> {{ busy ? '正在生成...' : '生成水印' }}</button></div><div class="side-panel"><div class="stat-row"><div class="stat-box"><div class="stat-num" style="color:#818cf8">{{ todayWatermarkCount }}</div><div class="stat-lbl">今日水印数</div></div><div class="stat-box"><div class="stat-num" style="color:#5eead4">{{ detectionSuccessRate }}</div><div class="stat-lbl">检测成功率</div></div></div><div class="section-title">可用水印方法</div><div class="method-list"><div class="method-item">DCT 频域 <span class="method-tag badge-blue">推荐</span></div><div class="method-item">空间域叠加 <span class="method-tag badge-green">快速</span></div><div class="method-item">DWT 小波变换 <span class="method-tag badge-amber">增强</span></div><div class="method-item">FFT 傅里叶 <span class="method-tag">最强</span></div></div></div></div></div><ResultDialog :open="dialogOpen" @close="dialogOpen=false"/></section>
</template>
